mapper.select:
SELECT COUNT(*) 
FROM customers c
WHERE c.is_deleted = 0

    AND (
        c.customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%')
        OR c.short_name LIKE CONCAT('%', #{query.customerKeyword}, '%')
        OR c.customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%')
    )


    AND c.customer_name LIKE CONCAT('%', #{query.customerName}, '%')


    AND c.customer_code LIKE CONCAT('%', #{query.customerCode}, '%')


    AND c.customer_type = #{query.customerType}


    AND c.customer_level = #{query.customerLevel}


    AND c.status = #{query.status}


    AND (

            c.sales = #{query.salesUserId}


            OR


            c.documentation_person = #{query.documentationPersonUserId}

    )

SELECT c.*, cc.contact_name AS primary_contact_name, cc.contact_mobile AS primary_contact_mobile, cc.contact_email AS primary_contact_email, (SELECT COUNT(*) FROM customer_contacts WHERE customer_id = c.id) AS contact_count, u1.real_name AS sales_user_name, u2.real_name AS documentation_person_user_name, (SELECT COALESCE(SUM(total_amount), 0) FROM sales_orders WHERE customer = c.customer_code AND is_deleted = 0 AND order_date >= DATE_FORMAT(NOW(), '%Y-01-01')) AS this_year_sales_amount, (SELECT COALESCE(SUM(total_amount), 0) FROM sales_orders WHERE customer = c.customer_code AND is_deleted = 0 AND order_date >= DATE_SUB(DATE_FORMAT(NOW(), '%Y-%m-01'), INTERVAL 1 MONTH) AND order_date < DATE_FORMAT(NOW(), '%Y-%m-01')) AS last_month_sales_amount, (SELECT COALESCE(SUM(total_amount), 0) FROM sales_orders WHERE customer = c.customer_code AND is_deleted = 0) AS shipped_amount FROM customers c LEFT JOIN ( SELECT c1.customer_id, c1.contact_name, c1.contact_mobile, c1.contact_email FROM customer_contacts c1 INNER JOIN ( SELECT customer_id, MIN(id) AS pick_id FROM customer_contacts WHERE is_primary = 1 GROUP BY customer_id ) p ON p.pick_id = c1.id ) cc ON c.id = cc.customer_id LEFT JOIN users u1 ON c.sales = u1.id LEFT JOIN users u2 ON c.documentation_person = u2.id WHERE c.is_deleted = 0
AND ( c.customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%') OR c.short_name LIKE CONCAT('%', #{query.customerKeyword}, '%') OR c.customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') )
AND c.customer_name LIKE CONCAT('%', #{query.customerName}, '%')
AND c.customer_code LIKE CONCAT('%', #{query.customerCode}, '%')
AND c.customer_type = #{query.customerType}
AND c.customer_level = #{query.customerLevel}
AND c.status = #{query.status}
AND (
c.sales = #{query.salesUserId}
OR
c.documentation_person = #{query.documentationPersonUserId}
)
ORDER BY c.create_time ORDER BY c.customer_code ORDER BY c.short_name ORDER BY c.customer_level ORDER BY c.status ORDER BY u1.real_name ORDER BY u2.real_name ORDER BY this_year_sales_amount ORDER BY last_month_sales_amount ORDER BY shipped_amount ORDER BY c.create_time
ASC DESC

SELECT IFNULL(SUM( CASE WHEN IFNULL(soi.rolls, 0) > 0 THEN IFNULL(dni.quantity, 0) * IFNULL(soi.amount, 0) / NULLIF(soi.rolls, 0) WHEN IFNULL(soi.sqm, 0) > 0 THEN IFNULL(dni.area_size, 0) * IFNULL(soi.amount, 0) / NULLIF(soi.sqm, 0) ELSE 0 END ), 0) FROM delivery_notices dn INNER JOIN delivery_notice_items dni ON dni.notice_id = dn.id INNER JOIN sales_order_items soi ON soi.id = dni.order_item_id AND soi.is_deleted = 0 WHERE dn.is_deleted = 0 AND ( UPPER(IFNULL(dn.status, '')) IN ('SHIPPED', 'RECEIVED') OR IFNULL(dn.status, '') IN ('已发货', '已收货') ) AND ( dn.customer COLLATE utf8mb4_unicode_ci IN
#{key} COLLATE utf8mb4_unicode_ci
)
